# owner: platform
"""Plain-text absence notices for parents."""

from datetime import date
from typing import Iterable, List

from rosterkit.models import Mark, Student


def _validate(student: Student, marks: List[Mark]):
    for mark in marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark belongs to {mark.student_id}"
            )


def _absent_days(marks: List[Mark]) -> List[date]:
    return sorted(
        mark.day for mark in marks
        if mark.status == "absent"
    )


def _require_days(days: List[date]):
    if not days:
        raise ValueError("no absences to report")


def _render(student: Student, days: List[date]) -> str:
    name = f"{student.first_name} {student.last_name}"
    count = len(days)
    noun = "day" if count == 1 else "days"
    listed = ", ".join(item.isoformat() for item in days)
    return (
        f"{name} missed {count} {noun}: {listed}."
    )


# ---
def build_absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    marks = list(marks)
    _validate(student, marks)
    days = _absent_days(marks)
    _require_days(days)
    return _render(student, days)
